package me.kright.gametools.pga3d

import scala.annotation.targetName
import me.kright.gametools.flatarray.FlatDoubleSerializer


/**
 * A bivector, the grade-2 element of 3d PGA: an unnormalized line in 3d, also used for rates of motion
 * (angular and linear velocity) in physics. The sum of a Pga3dBivectorBulk and a Pga3dBivectorWeight part.
 * bivector.exp is a Pga3dMotor, and motor.log is a Pga3dBivector.
 *
 * Variable fields: wx, wy, wz, xy, xz, yz.
 *
 * Generated by pgaNdCodeGen (me.kright.gametools.pga.codegen.scalagen.pga3d.runScalaCodeGen).
 * Do not edit by hand: change the generator and re-run it.
 */
final case class Pga3dBivector(wx: Double = 0.0,
                               wy: Double = 0.0,
                               wz: Double = 0.0,
                               xy: Double = 0.0,
                               xz: Double = 0.0,
                               yz: Double = 0.0) derives CanEqual, FlatDoubleSerializer:

  override def toString: String =
    s"Pga3dBivector(wx = $wx, wy = $wy, wz = $wz, xy = $xy, xz = $xz, yz = $yz)"

  def dual: Pga3dBivector =
    Pga3dBivector(
      wx = yz,
      wy = -xz,
      wz = xy,
      xy = wz,
      xz = -wy,
      yz = wx,
    )

  def weight: Pga3dBivectorWeight =
    Pga3dBivectorWeight(
      wx = wx,
      wy = wy,
      wz = wz,
    )

  def bulk: Pga3dBivectorBulk =
    Pga3dBivectorBulk(
      xy = xy,
      xz = xz,
      yz = yz,
    )

  @targetName("unaryMinus")
  def unary_- : Pga3dBivector =
    Pga3dBivector(
      wx = -wx,
      wy = -wy,
      wz = -wz,
      xy = -xy,
      xz = -xz,
      yz = -yz,
    )

  def reverse: Pga3dBivector =
    -this

  def antiReverse: Pga3dBivector =
    -this

  def bulkNormSquare: Double =
    (xy * xy + xz * xz + yz * yz)

  def bulkNorm: Double =
    Math.sqrt(bulkNormSquare)

  def normalizedByBulk =
    this / bulkNorm

  def weightNormSquare: Double =
    (wx * wx + wy * wy + wz * wz)

  def weightNorm: Double =
    Math.sqrt(weightNormSquare)

  def normalizedByWeight =
    this / weightNorm

  def normSquare: Double =
    (wx * wx + wy * wy + wz * wz + xy * xy + xz * xz + yz * yz)

  def norm: Double =
    Math.sqrt(normSquare)

  def normalizedByNorm =
    this / norm

  @targetName("times")
  def *(r: Double): Pga3dBivector =
    Pga3dBivector(
      wx = r * wx,
      wy = r * wy,
      wz = r * wz,
      xy = r * xy,
      xz = r * xz,
      yz = r * yz,
    )

  /** multiplies by the reciprocal: one division instead of one per component, at the cost of one extra rounding (~0.5 ulp) */
  @targetName("div")
  def /(r: Double): Pga3dBivector =
    this * (1.0 / r)

  @targetName("plus")
  def +(r: Pga3dBivector): Pga3dBivector =
    Pga3dBivector(
      wx = (r.wx + wx),
      wy = (r.wy + wy),
      wz = (r.wz + wz),
      xy = (r.xy + xy),
      xz = (r.xz + xz),
      yz = (r.yz + yz),
    )

  @targetName("minus")
  def -(r: Pga3dBivector): Pga3dBivector =
    Pga3dBivector(
      wx = (wx - r.wx),
      wy = (wy - r.wy),
      wz = (wz - r.wz),
      xy = (xy - r.xy),
      xz = (xz - r.xz),
      yz = (yz - r.yz),
    )

  def madd(r: Pga3dBivector, mult: Double): Pga3dBivector =
    Pga3dBivector(
      wx = (wx + mult * r.wx),
      wy = (wy + mult * r.wy),
      wz = (wz + mult * r.wz),
      xy = (xy + mult * r.xy),
      xz = (xz + mult * r.xz),
      yz = (yz + mult * r.yz),
    )

  @targetName("plus")
  def +(r: Pga3dBivectorBulk): Pga3dBivector =
    Pga3dBivector(
      wx = wx,
      wy = wy,
      wz = wz,
      xy = (r.xy + xy),
      xz = (r.xz + xz),
      yz = (r.yz + yz),
    )

  @targetName("minus")
  def -(r: Pga3dBivectorBulk): Pga3dBivector =
    Pga3dBivector(
      wx = wx,
      wy = wy,
      wz = wz,
      xy = (xy - r.xy),
      xz = (xz - r.xz),
      yz = (yz - r.yz),
    )

  def madd(r: Pga3dBivectorBulk, mult: Double): Pga3dBivector =
    Pga3dBivector(
      wx = wx,
      wy = wy,
      wz = wz,
      xy = (xy + mult * r.xy),
      xz = (xz + mult * r.xz),
      yz = (yz + mult * r.yz),
    )

  @targetName("plus")
  def +(r: Pga3dBivectorWeight): Pga3dBivector =
    Pga3dBivector(
      wx = (r.wx + wx),
      wy = (r.wy + wy),
      wz = (r.wz + wz),
      xy = xy,
      xz = xz,
      yz = yz,
    )

  @targetName("minus")
  def -(r: Pga3dBivectorWeight): Pga3dBivector =
    Pga3dBivector(
      wx = (wx - r.wx),
      wy = (wy - r.wy),
      wz = (wz - r.wz),
      xy = xy,
      xz = xz,
      yz = yz,
    )

  def madd(r: Pga3dBivectorWeight, mult: Double): Pga3dBivector =
    Pga3dBivector(
      wx = (wx + mult * r.wx),
      wy = (wy + mult * r.wy),
      wz = (wz + mult * r.wz),
      xy = xy,
      xz = xz,
      yz = yz,
    )

  /** componentwise product on the raw fields; NOT a geometric-algebra operation (basis-dependent) */
  def scale(r: Pga3dBivector): Pga3dBivector =
    Pga3dBivector(
      wx = wx * r.wx,
      wy = wy * r.wy,
      wz = wz * r.wz,
      xy = xy * r.xy,
      xz = xz * r.xz,
      yz = yz * r.yz,
    )

  /** componentwise 1/x on the raw fields (a zero field yields Infinity); NOT the multiplicative inverse */
  def reciprocal: Pga3dBivector =
    Pga3dBivector(
      wx = 1.0 / wx,
      wy = 1.0 / wy,
      wz = 1.0 / wz,
      xy = 1.0 / xy,
      xz = 1.0 / xz,
      yz = 1.0 / yz,
    )

  def exp: Pga3dMotor =
    val len = bulkNorm
    val cos = Math.cos(len)

    // sin(x)/x = 1 - x^2/6 + x^4/120 - ...; at x <= 1e-5 the dropped x^4/120 <= 8.4e-23
    // relative term is far below 1e-17, so the second-order form is exact in double
    val sinDivLen = if (len > 1e-5) {
      Math.sin(len) / len
    } else {
      1.0 - (len * len) / 6.0
    }

    // (sin(x)/x - cos(x)) / x^2, step by step:
    //   sin(x)   = x - x^3/6 + x^5/120 - x^7/5040 + ...
    //   sin(x)/x = 1 - x^2/6 + x^4/120 - x^6/5040 + ...
    //   cos(x)   = 1 - x^2/2 + x^4/24  - x^6/720  + ...
    //   sin(x)/x - cos(x) = (1/2 - 1/6)*x^2 + (1/120 - 1/24)*x^4 + (1/720 - 1/5040)*x^6 + ...
    //                     = x^2/3 - x^4/30 + x^6/840 - ...
    //   divide by x^2:      1/3   - x^2/30 + x^4/840 - ...
    // at x <= 1e-5 the dropped x^4/840 <= 1.2e-23 is relatively far below 1e-17,
    // so the second-order form is exact in double
    val sinMinusCosDivLen2 = if (len > 1e-5) {
      (sinDivLen - cos) / (len * len)
    } else {
      1.0 / 3.0 - (len * len) / 30.0
    }

    Pga3dMotor(
      s = cos,
      wx = (sinDivLen * wx + sinMinusCosDivLen2 * yz * (wy * xz - wx * yz - wz * xy)),
      wy = (sinDivLen * wy + sinMinusCosDivLen2 * xz * (wx * yz + wz * xy - wy * xz)),
      wz = (sinDivLen * wz + sinMinusCosDivLen2 * xy * (wy * xz - wx * yz - wz * xy)),
      xy = sinDivLen * xy,
      xz = sinDivLen * xz,
      yz = sinDivLen * yz,
      i = sinDivLen * (wx * yz + wz * xy - wy * xz),
    )

  /** for components below ~1e-154 the pairwise field products of this t-factored form may underflow; (b * t).exp does not */
  def exp(t: Double): Pga3dMotor =
    val len = bulkNorm * Math.abs(t)
    val cos = Math.cos(len)

    // sin(x)/x = 1 - x^2/6 + x^4/120 - ...; at x <= 1e-5 the dropped x^4/120 <= 8.4e-23
    // relative term is far below 1e-17, so the second-order form is exact in double
    val sinDivLen = if (len > 1e-5) {
      Math.sin(len) / len
    } else {
      1.0 - (len * len) / 6.0
    }

    // (sin(x)/x - cos(x)) / x^2, step by step:
    //   sin(x)   = x - x^3/6 + x^5/120 - x^7/5040 + ...
    //   sin(x)/x = 1 - x^2/6 + x^4/120 - x^6/5040 + ...
    //   cos(x)   = 1 - x^2/2 + x^4/24  - x^6/720  + ...
    //   sin(x)/x - cos(x) = (1/2 - 1/6)*x^2 + (1/120 - 1/24)*x^4 + (1/720 - 1/5040)*x^6 + ...
    //                     = x^2/3 - x^4/30 + x^6/840 - ...
    //   divide by x^2:      1/3   - x^2/30 + x^4/840 - ...
    // at x <= 1e-5 the dropped x^4/840 <= 1.2e-23 is relatively far below 1e-17,
    // so the second-order form is exact in double
    val sinMinusCosDivLen2 = if (len > 1e-5) {
      (sinDivLen - cos) / (len * len)
    } else {
      1.0 / 3.0 - (len * len) / 30.0
    }

    Pga3dMotor(
      s = cos,
      wx = t * (sinDivLen * wx + sinMinusCosDivLen2 * t * t * yz * (wy * xz - wx * yz - wz * xy)),
      wy = t * (sinDivLen * wy + sinMinusCosDivLen2 * t * t * xz * (wx * yz + wz * xy - wy * xz)),
      wz = t * (sinDivLen * wz + sinMinusCosDivLen2 * t * t * xy * (wy * xz - wx * yz - wz * xy)),
      xy = sinDivLen * t * xy,
      xz = sinDivLen * t * xz,
      yz = sinDivLen * t * yz,
      i = sinDivLen * t * t * (wx * yz + wz * xy - wy * xz),
    )

  def split: (Pga3dBivector, Pga3dBivectorWeight) =
    val div = bulkNormSquare
    if (div < 1e-100) {
      return (Pga3dBivector(0.0, 0.0, 0.0, xy, xz, yz), Pga3dBivectorWeight(wx, wy, wz))
    }

    // shiftAlongLine = this.geometric((this ^ this.reverse) / div / 2.0)
    val pseudoScalar = (wy * xz - wx * yz - wz * xy) / div
    val shiftAlongLine = Pga3dBivectorWeight(
      wx = -pseudoScalar * yz,
      wy = pseudoScalar * xz,
      wz = -pseudoScalar * xy,
    )

    val line = this - shiftAlongLine
    (line, shiftAlongLine)

  def toMultivector: Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = 0.0,
      x = 0.0,
      y = 0.0,
      z = 0.0,
      wx = wx,
      wy = wy,
      wz = wz,
      xy = xy,
      xz = xz,
      yz = yz,
      wxy = 0.0,
      wxz = 0.0,
      wyz = 0.0,
      xyz = 0.0,
      i = 0.0,
    )

  def toMotor: Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
      wx = wx,
      wy = wy,
      wz = wz,
      xy = xy,
      xz = xz,
      yz = yz,
      i = 0.0,
    )

  def toRotorUnsafe: Pga3dRotor =
    Pga3dRotor(
      s = 0.0,
      xy = xy,
      xz = xz,
      yz = yz,
    )

  def toProjectiveTranslatorUnsafe: Pga3dProjectiveTranslator =
    Pga3dProjectiveTranslator(
      s = 0.0,
      wx = wx,
      wy = wy,
      wz = wz,
    )

  def toTranslatorUnsafe: Pga3dTranslator =
    Pga3dTranslator(
      wx = wx,
      wy = wy,
      wz = wz,
    )

  def toBivectorBulkUnsafe: Pga3dBivectorBulk =
    Pga3dBivectorBulk(
      xy = xy,
      xz = xz,
      yz = yz,
    )

  def toBivectorWeightUnsafe: Pga3dBivectorWeight =
    Pga3dBivectorWeight(
      wx = wx,
      wy = wy,
      wz = wz,
    )

  /** fused -plane.dot(line).geometric(plane); the result is the line scaled by plane.normSquare > 0 */
  def projectOntoPlane(plane: Pga3dPlane): Pga3dBivector =
    Pga3dBivector(
      wx = (plane.w * (-plane.y * xy - plane.z * xz) + plane.x * (plane.x * wx + plane.y * wy + plane.z * wz)),
      wy = (plane.w * (plane.x * xy - plane.z * yz) + plane.y * (plane.x * wx + plane.y * wy + plane.z * wz)),
      wz = (plane.w * (plane.x * xz + plane.y * yz) + plane.z * (plane.x * wx + plane.y * wy + plane.z * wz)),
      xy = (plane.x * (plane.x * xy - plane.z * yz) + plane.y * (plane.y * xy + plane.z * xz)),
      xz = (plane.x * (plane.x * xz + plane.y * yz) + plane.z * (plane.y * xy + plane.z * xz)),
      yz = (plane.x * (plane.y * xz - plane.z * xy) + yz * (plane.y * plane.y + plane.z * plane.z)),
    )

  /** fused -plane.dot(line).geometric(plane); the result is the line scaled by plane.normSquare > 0 */
  def projectOntoPlane(plane: Pga3dPlaneCentral): Pga3dBivector =
    Pga3dBivector(
      wx = plane.x * (plane.x * wx + plane.y * wy + plane.z * wz),
      wy = plane.y * (plane.x * wx + plane.y * wy + plane.z * wz),
      wz = plane.z * (plane.x * wx + plane.y * wy + plane.z * wz),
      xy = (plane.x * (plane.x * xy - plane.z * yz) + plane.y * (plane.y * xy + plane.z * xz)),
      xz = (plane.x * (plane.x * xz + plane.y * yz) + plane.z * (plane.y * xy + plane.z * xz)),
      yz = (plane.x * (plane.y * xz - plane.z * xy) + yz * (plane.y * plane.y + plane.z * plane.z)),
    )

  infix def geometric(r: Pga3dMotor): Pga3dMotor =
    Pga3dMotor(
      s = (-r.xy * xy - r.xz * xz - r.yz * yz),
      wx = (r.s * wx + r.wy * xy + r.wz * xz - r.i * yz - r.xy * wy - r.xz * wz),
      wy = (r.i * xz + r.s * wy + r.wz * yz + r.xy * wx - r.wx * xy - r.yz * wz),
      wz = (r.s * wz + r.xz * wx + r.yz * wy - r.i * xy - r.wx * xz - r.wy * yz),
      xy = (r.s * xy + r.xz * yz - r.yz * xz),
      xz = (r.s * xz + r.yz * xy - r.xy * yz),
      yz = (r.s * yz + r.xy * xz - r.xz * xy),
      i = (r.wx * yz + r.wz * xy + r.xy * wz + r.yz * wx - r.wy * xz - r.xz * wy),
    )

  infix def geometric(r: Pga3dPlane): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (r.x * wx + r.y * wy + r.z * wz),
      x = (r.y * xy + r.z * xz),
      y = (r.z * yz - r.x * xy),
      z = (-r.x * xz - r.y * yz),
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.w * xy + r.y * wx - r.x * wy),
      wxz = (r.w * xz + r.z * wx - r.x * wz),
      wyz = (r.w * yz + r.z * wy - r.y * wz),
      xyz = (r.x * yz + r.z * xy - r.y * xz),
      i = 0.0,
    )

  infix def geometric(r: Pga3dBivector): Pga3dMotor =
    Pga3dMotor(
      s = (-r.xy * xy - r.xz * xz - r.yz * yz),
      wx = (r.wy * xy + r.wz * xz - r.xy * wy - r.xz * wz),
      wy = (r.wz * yz + r.xy * wx - r.wx * xy - r.yz * wz),
      wz = (r.xz * wx + r.yz * wy - r.wx * xz - r.wy * yz),
      xy = (r.xz * yz - r.yz * xz),
      xz = (r.yz * xy - r.xy * yz),
      yz = (r.xy * xz - r.xz * xy),
      i = (r.wx * yz + r.wz * xy + r.xy * wz + r.yz * wx - r.wy * xz - r.xz * wy),
    )

  infix def geometric(r: Pga3dProjectivePoint): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (r.x * yz + r.z * xy - r.y * xz),
      x = -r.w * yz,
      y = r.w * xz,
      z = -r.w * xy,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.w * wz + r.x * xz + r.y * yz),
      wxz = (r.z * yz - r.w * wy - r.x * xy),
      wyz = (r.w * wx - r.y * xy - r.z * xz),
      xyz = 0.0,
      i = 0.0,
    )

  infix def geometric(r: Pga3dRotor): Pga3dMotor =
    Pga3dMotor(
      s = (-r.xy * xy - r.xz * xz - r.yz * yz),
      wx = (r.s * wx - r.xy * wy - r.xz * wz),
      wy = (r.s * wy + r.xy * wx - r.yz * wz),
      wz = (r.s * wz + r.xz * wx + r.yz * wy),
      xy = (r.s * xy + r.xz * yz - r.yz * xz),
      xz = (r.s * xz + r.yz * xy - r.xy * yz),
      yz = (r.s * yz + r.xy * xz - r.xz * xy),
      i = (r.xy * wz + r.yz * wx - r.xz * wy),
    )

  infix def geometric(r: Pga3dProjectiveTranslator): Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
      wx = (r.s * wx + r.wy * xy + r.wz * xz),
      wy = (r.s * wy + r.wz * yz - r.wx * xy),
      wz = (r.s * wz - r.wx * xz - r.wy * yz),
      xy = r.s * xy,
      xz = r.s * xz,
      yz = r.s * yz,
      i = (r.wx * yz + r.wz * xy - r.wy * xz),
    )

  infix def geometric(r: Pga3dTranslator): Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
      wx = (wx + r.wy * xy + r.wz * xz),
      wy = (wy + r.wz * yz - r.wx * xy),
      wz = (wz - r.wx * xz - r.wy * yz),
      xy = xy,
      xz = xz,
      yz = yz,
      i = (r.wx * yz + r.wz * xy - r.wy * xz),
    )

  infix def geometric(r: Pga3dVector): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (r.x * yz + r.z * xy - r.y * xz),
      x = 0.0,
      y = 0.0,
      z = 0.0,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.x * xz + r.y * yz),
      wxz = (r.z * yz - r.x * xy),
      wyz = (-r.y * xy - r.z * xz),
      xyz = 0.0,
      i = 0.0,
    )

  infix def geometric(r: Pga3dPoint): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (r.x * yz + r.z * xy - r.y * xz),
      x = -yz,
      y = xz,
      z = -xy,
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (wz + r.x * xz + r.y * yz),
      wxz = (-wy + r.z * yz - r.x * xy),
      wyz = (wx - r.y * xy - r.z * xz),
      xyz = 0.0,
      i = 0.0,
    )

  infix def geometric(r: Pga3dPlaneCentral): Pga3dMultivector =
    Pga3dMultivector(
      s = 0.0,
      w = (r.x * wx + r.y * wy + r.z * wz),
      x = (r.y * xy + r.z * xz),
      y = (r.z * yz - r.x * xy),
      z = (-r.x * xz - r.y * yz),
      wx = 0.0,
      wy = 0.0,
      wz = 0.0,
      xy = 0.0,
      xz = 0.0,
      yz = 0.0,
      wxy = (r.y * wx - r.x * wy),
      wxz = (r.z * wx - r.x * wz),
      wyz = (r.z * wy - r.y * wz),
      xyz = (r.x * yz + r.z * xy - r.y * xz),
      i = 0.0,
    )

  infix def geometric(r: Pga3dBivectorBulk): Pga3dMotor =
    Pga3dMotor(
      s = (-r.xy * xy - r.xz * xz - r.yz * yz),
      wx = (-r.xy * wy - r.xz * wz),
      wy = (r.xy * wx - r.yz * wz),
      wz = (r.xz * wx + r.yz * wy),
      xy = (r.xz * yz - r.yz * xz),
      xz = (r.yz * xy - r.xy * yz),
      yz = (r.xy * xz - r.xz * xy),
      i = (r.xy * wz + r.yz * wx - r.xz * wy),
    )

  infix def geometric(r: Pga3dBivectorWeight): Pga3dMotor =
    Pga3dMotor(
      s = 0.0,
